-- migration-class: contract — register tenant evaluation preferences and operator-owned enrollment history.
SET LOCAL lock_timeout = '2s';

-- BEGIN GENERATED by console-settings-domain examples/setting_definitions.rs
INSERT INTO setting_definitions
    (key, kind, min_value, max_value, default_ordinal, looser_when, governance, codes)
VALUES
('module.evaluation.enabled', 'bool', NULL::BIGINT, NULL::BIGINT, 1::BIGINT, 'neutral', 'tenant', NULL::TEXT[])
ON CONFLICT (key) DO UPDATE SET
    kind = EXCLUDED.kind, min_value = EXCLUDED.min_value, max_value = EXCLUDED.max_value,
    default_ordinal = EXCLUDED.default_ordinal, looser_when = EXCLUDED.looser_when,
    governance = EXCLUDED.governance, codes = EXCLUDED.codes;
-- END GENERATED

-- Enrollment is a release decision. Runtime tenant credentials never write it.
CREATE TABLE tenant_module_enrollments (
    revision BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    org_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT,
    module_key TEXT NOT NULL CHECK (module_key IN ('evaluation')),
    enabled BOOLEAN NOT NULL,
    change_ref TEXT NOT NULL CHECK (char_length(btrim(change_ref)) BETWEEN 1 AND 128),
    recorded_by NAME NOT NULL DEFAULT session_user,
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (org_id, module_key, change_ref)
);
CREATE INDEX tenant_module_enrollment_latest ON tenant_module_enrollments (org_id, module_key, revision DESC);
ALTER TABLE tenant_module_enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant_module_enrollments FORCE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON tenant_module_enrollments
    USING (org_id = NULLIF(current_setting('app.current_org', true), '')::UUID)
    WITH CHECK (org_id = NULLIF(current_setting('app.current_org', true), '')::UUID);
REVOKE ALL ON tenant_module_enrollments FROM PUBLIC, console_rt;
GRANT SELECT (org_id, module_key, enabled, revision) ON tenant_module_enrollments TO console_rt;
COMMENT ON COLUMN tenant_module_enrollments.revision IS 'pd:none — enrollment decision order';
COMMENT ON COLUMN tenant_module_enrollments.org_id IS 'pd:none — tenant scope';
COMMENT ON COLUMN tenant_module_enrollments.module_key IS 'pd:none — release module identifier';
COMMENT ON COLUMN tenant_module_enrollments.enabled IS 'pd:none — explicit enrollment decision';
COMMENT ON COLUMN tenant_module_enrollments.change_ref IS 'pd:none — opaque release change reference';
COMMENT ON COLUMN tenant_module_enrollments.recorded_by IS 'pd:personal — database operator principal recording the decision';
COMMENT ON COLUMN tenant_module_enrollments.recorded_at IS 'pd:none — release decision timestamp';
